package com.harshith.book.service;
import com.harshith.book.entity.*; import com.harshith.book.exception.*; import com.harshith.book.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class IssueService{
 private final IssueRecordRepository issues; private final BookRepository books; private final UserRepository users;
 public IssueService(IssueRecordRepository i,BookRepository b,UserRepository u){issues=i;books=b;users=u;}
 public IssueRecord issue(Long bookId,Long userId){Book b=books.findById(bookId).orElseThrow(()->new ResourceNotFoundException("Book not found"));User u=users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found"));if(b.getAvailableQuantity()<=0)throw new BusinessException("Book is not available");b.setAvailableQuantity(b.getAvailableQuantity()-1);books.save(b);IssueRecord r=new IssueRecord();r.setBook(b);r.setUser(u);r.setIssueDate(LocalDate.now());r.setReturned(false);return issues.save(r);}
 public IssueRecord returnBook(Long id){IssueRecord r=issues.findById(id).orElseThrow(()->new ResourceNotFoundException("Issue record not found"));if(r.isReturned())throw new BusinessException("Book already returned");r.setReturned(true);r.setReturnDate(LocalDate.now());Book b=r.getBook();b.setAvailableQuantity(b.getAvailableQuantity()+1);books.save(b);return issues.save(r);}
 public List<IssueRecord> all(){return issues.findAll();} public List<IssueRecord> byUser(Long id){return issues.findByUserId(id);} public List<IssueRecord> byBook(Long id){return issues.findByBookId(id);}
}